const b = ($json.body && Object.keys($json.body).length) ? $json.body : $json;
const raw = String(b.q || b.query || "").trim();
const mode = ["keyword","semantic","hybrid"].includes(b.mode) ? b.mode : "hybrid";
const page = Math.max(1, parseInt(b.page, 10) || 1);
const pageSize = Math.min(50, Math.max(1, parseInt(b.pageSize, 10) || 10));
const topK = Math.min(100, Math.max(pageSize, parseInt(b.topK, 10) || 50));
const wantRag = b.rag === true || b.rag === "true";
// query parser: extract "quoted phrases" and field:filters
const phrases = (raw.match(/"([^"]+)"/g) || []).map(function(p){ return p.replace(/"/g,""); });
const filters = {};
const filterRe = /(\w+):([^\s]+)/g; let m;
while ((m = filterRe.exec(raw)) !== null) { filters[m[1]] = m[2]; }
let cleaned = raw.replace(/"[^"]+"/g, " ").replace(/\w+:[^\s]+/g, " ");
// tokenizer + normalization
const stop = new Set(["the","a","an","of","to","and","or","in","on","for","is","are"]);
const tokens = cleaned.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(function(t){ return t && !stop.has(t); });
const normalizedQuery = tokens.join(" ") || raw.toLowerCase();
// lightweight synonym expansion
const syn = { js: ["javascript"], ts: ["typescript"], db: ["database"], ml: ["machine","learning"] };
const expansions = [];
tokens.forEach(function(t){ if (syn[t]) { syn[t].forEach(function(s){ expansions.push(s); }); } });
// naive language + intent detection
const language = /[^\x00-\x7F]/.test(raw) ? "non-en" : "en";
const intent = /\b(how|what|why|when|who|where)\b/i.test(raw) ? "question" : "lookup";
return [{ json: { raw, normalizedQuery, tokens, phrases, filters, expansions, language, intent, mode, page, pageSize, topK, wantRag } }];

const q = $("Parse Query").first().json;
const items = $input.all();
const out = items.filter(function(i){ return i.json && i.json.id != null; }).map(function(i){
  const d = i.json;
  const title = String(d.title || "").toLowerCase();
  const titleBoost = q.tokens.some(function(t){ return title.indexOf(t) >= 0; }) ? 1.5 : 1.0;
  const phraseBoost = (q.phrases || []).some(function(p){ return String(d.content||"").toLowerCase().indexOf(p.toLowerCase()) >= 0; }) ? 1.3 : 1.0;
  const bm25 = Number(d.bm25 || 0) * titleBoost * phraseBoost;
  return { json: { id: d.id, url: d.url, title: d.title, content: d.content, source: d.source, quality: Number(d.quality||0.5), popularity: Number(d.popularity||0), updated_at: d.updated_at, bm25: bm25, semantic: 0, origin: "bm25" } };
});
return out;

const res = $input.first().json || {};
const hits = (res.result || res.points || []);
const out = hits.map(function(h){
  const p = h.payload || {};
  return { json: { id: p.docId || p.id || h.id, url: p.url || "", title: p.title || "", content: p.text || p.content || "", source: p.source || "vector", quality: Number(p.quality||0.5), popularity: Number(p.popularity||0), updated_at: p.updated_at || null, bm25: 0, semantic: Number(h.score||0), origin: "semantic" } };
});
return out.length ? out : [{ json: { __empty: true, bm25: 0, semantic: 0 } }];

const q = $("Parse Query").first().json;
const rows = $input.all().map(function(i){ return i.json; }).filter(function(r){ return r && !r.__empty && r.id != null; });
// score normalization (min-max) per signal
function norm(vals){ const mn=Math.min.apply(null, vals); const mx=Math.max.apply(null, vals); const d=mx-mn; return function(v){ return d>0 ? (v-mn)/d : 0; }; }
const bm = rows.length ? norm(rows.map(function(r){return Number(r.bm25||0);})) : function(){return 0;};
const sm = rows.length ? norm(rows.map(function(r){return Number(r.semantic||0);})) : function(){return 0;};
// candidate merging + duplicate removal by id
const byId = {};
rows.forEach(function(r){
  const k = String(r.id);
  if (!byId[k]) { byId[k] = Object.assign({}, r, { nBm25: bm(Number(r.bm25||0)), nSem: sm(Number(r.semantic||0)) }); }
  else { byId[k].nBm25 = Math.max(byId[k].nBm25, bm(Number(r.bm25||0))); byId[k].nSem = Math.max(byId[k].nSem, sm(Number(r.semantic||0))); }
});
let merged = Object.keys(byId).map(function(k){ return byId[k]; });
// weighting by mode, with BM25 fallback when no semantic signal
const hasSem = merged.some(function(r){ return r.nSem > 0; });
let wB = 0.5, wS = 0.5;
if (q.mode === "keyword" || !hasSem) { wB = 1; wS = 0; }
else if (q.mode === "semantic") { wB = 0.15; wS = 0.85; }
merged.forEach(function(r){ r.fused = wB * r.nBm25 + wS * r.nSem; });
merged.sort(function(a,b){ return b.fused - a.fused; });
return merged.slice(0, q.topK).map(function(r){ return { json: r }; });

const q = $("Parse Query").first().json;
const now = Date.now();
// configurable ranking weights
const W = { fused: 0.45, title: 0.12, url: 0.06, phrase: 0.08, freshness: 0.08, quality: 0.07, authority: 0.06, popularity: 0.08 };
function authorityOf(u){ try { const h = new URL(u).hostname; if (/\.(gov|edu)$/.test(h)) return 1; if (/wikipedia|github|docs\./.test(h)) return 0.8; return 0.5; } catch(e){ return 0.4; } }
const rows = $input.all().map(function(i){ return i.json; });
const out = rows.map(function(r){
  const title = String(r.title||"").toLowerCase();
  const url = String(r.url||"").toLowerCase();
  const titleMatch = q.tokens.filter(function(t){ return title.indexOf(t)>=0; }).length / Math.max(1, q.tokens.length);
  const urlMatch = q.tokens.some(function(t){ return url.indexOf(t)>=0; }) ? 1 : 0;
  const phraseMatch = (q.phrases||[]).some(function(p){ return String(r.content||"").toLowerCase().indexOf(p.toLowerCase())>=0; }) ? 1 : 0;
  const ageDays = r.updated_at ? (now - new Date(r.updated_at).getTime())/86400000 : 365;
  const freshness = Math.max(0, 1 - ageDays/365);
  const quality = Number(r.quality||0.5);
  const authority = authorityOf(r.url);
  const popularity = Math.min(1, Number(r.popularity||0)/100);
  const score = W.fused*Number(r.fused||0) + W.title*titleMatch + W.url*urlMatch + W.phrase*phraseMatch + W.freshness*freshness + W.quality*quality + W.authority*authority + W.popularity*popularity;
  return { json: Object.assign({}, r, { titleMatch, urlMatch, phraseMatch, freshness, authority, score }) };
});
out.sort(function(a,b){ return b.json.score - a.json.score; });
return out;

const q = $("Parse Query").first().json;
const rows = $input.all().map(function(i){ return i.json; });
function snippet(text, tokens){
  const t = String(text||""); const low = t.toLowerCase();
  let pos = -1; for (let i=0;i<tokens.length;i++){ const p = low.indexOf(tokens[i]); if (p>=0){ pos=p; break; } }
  if (pos<0) pos=0; const start=Math.max(0,pos-60); const end=Math.min(t.length,pos+140);
  let s = t.slice(start,end).trim(); if(start>0) s="..."+s; if(end<t.length) s=s+"..."; return s;
}
const total = rows.length;
const start = (q.page-1)*q.pageSize;
const pageRows = rows.slice(start, start+q.pageSize).map(function(r,idx){
  return { rank: start+idx+1, id: r.id, url: r.url, title: r.title, score: Number((r.score||0).toFixed(4)), snippet: snippet(r.content, q.tokens) };
});
// facets over source
const facets = {}; rows.forEach(function(r){ const s=r.source||"unknown"; facets[s]=(facets[s]||0)+1; });
// related searches + autocomplete suggestions
const related = (q.expansions||[]).concat(q.tokens.slice(0,2).map(function(t){ return t + " tutorial"; }));
const suggestions = q.tokens.map(function(t){ return q.normalizedQuery + " " + t; }).slice(0,5);
const payload = { query: q.raw, mode: q.mode, page: q.page, pageSize: q.pageSize, total: total, totalPages: Math.ceil(total/q.pageSize), results: pageRows, facets: facets, related: related, suggestions: suggestions };
return [{ json: payload }];

const data = $json;
const q = $("Parse Query").first().json;
const ctx = (data.results||[]).slice(0,5).map(function(r,i){ return "[" + (i+1) + "] " + (r.title||"") + " (" + (r.url||"") + ")\n" + (r.snippet||""); }).join("\n\n");
const system = "You are Nexus Search. Answer ONLY from the numbered sources. Cite sources as [n]. If the answer is not present, say you do not know.";
const user = "Question: " + q.raw + "\n\nSources:\n" + ctx;
const payload = { model: "gpt-4o-mini", temperature: 0.2, messages: [ { role: "system", content: system }, { role: "user", content: user } ] };
return [{ json: { payload: payload, results: data.results, base: data } }];

const resp = $json;
const base = $("Build Prompt").first().json.base;
const results = $("Build Prompt").first().json.results || [];
let answer = "";
try { answer = resp.choices[0].message.content || ""; } catch(e) { answer = ""; }
// citation verification: keep only [n] that map to a real source
const cited = (answer.match(/\[(\d+)\]/g) || []).map(function(x){ return parseInt(x.replace(/[^0-9]/g,""),10); });
const uniqueCited = Array.from(new Set(cited)).filter(function(n){ return n>=1 && n<=results.length; });
const sources = uniqueCited.map(function(n){ const r = results[n-1]; return { n: n, title: r.title, url: r.url }; });
// simple confidence: grounded citations vs. answer presence
const confidence = answer && sources.length ? Math.min(1, 0.4 + 0.15*sources.length) : (answer ? 0.3 : 0);
const out = Object.assign({}, base, { answer: answer, sources: sources, confidence: Number(confidence.toFixed(2)) });
return [{ json: out }];

const b = ($json.body && Object.keys($json.body).length) ? $json.body : $json;
const name = String(b.filename || b.name || "document.txt");
const ext = (name.split(".").pop() || "txt").toLowerCase();
const map = { pdf:"application/pdf", csv:"text/csv", xlsx:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", xls:"application/vnd.ms-excel", html:"text/html", htm:"text/html", md:"text/markdown", json:"application/json", txt:"text/plain" };
const mime = b.mime || map[ext] || "text/plain";
let kind = "text";
if (ext === "pdf") kind = "pdf";
else if (["xlsx","xls","csv","ods"].indexOf(ext) >= 0) kind = "spreadsheet";
else if (["html","htm"].indexOf(ext) >= 0) kind = "html";
const url = b.url || b.canonicalUrl || ("nexus://upload/" + name);
let canonical = url; try { const u = new URL(url); u.hash=""; u.search=""; canonical = u.toString(); } catch(e){}
const meta = { filename: name, ext: ext, mime: mime, kind: kind, canonical: canonical, source: b.source || "upload", ingestedAt: new Date().toISOString(), rawText: b.text || b.content || "" };
return [{ json: meta }];

const meta = $("Detect MIME & Metadata").first().json;
const src = $json;
let text = "";
if (typeof src.text === "string" && src.text) text = src.text;
else if (src.extractedText) text = src.extractedText;
else if (src.body) text = String(src.title? (src.title+"\n"+src.body):src.body);
else if (Array.isArray(src.data)) text = src.data.map(function(r){ return Object.values(r).join(" "); }).join("\n");
else text = String(meta.rawText||"");
text = text.replace(/\s+/g," ").trim();
// content quality scoring
const words = text ? text.split(" ").length : 0;
const uniq = new Set(text.toLowerCase().split(" ")).size;
const diversity = words ? uniq/words : 0;
let quality = Math.min(1, (words/800)*0.6 + diversity*0.4);
if (words < 20) quality = 0.1;
const title = src.title || meta.filename;
const doc = { canonical: meta.canonical, url: meta.canonical, title: title, source: meta.source, mime: meta.mime, kind: meta.kind, ingestedAt: meta.ingestedAt, wordCount: words, quality: Number(quality.toFixed(3)), content: text };
return [{ json: doc }];

const d = $("Content Hash").first().json;
const text = String(d.content||"");
const size = 800; const overlap = 120;
const chunks = [];
let i = 0, idx = 0;
while (i < text.length) { const end = Math.min(text.length, i+size); chunks.push({ index: idx, text: text.slice(i, end) }); idx++; i = end - overlap; if (i < 0) i = 0; if (end === text.length) break; }
if (!chunks.length) chunks.push({ index: 0, text: text });
const doc = Object.assign({}, d, { chunks: chunks, chunkCount: chunks.length });
return [{ json: doc }];

const items = $input.all();
const out = [];
const domainCount = {};
items.forEach(function(i){
  let raw = String((i.json.url != null ? i.json.url : i.json) || "");
  let ok = true, host = "";
  try { const u = new URL(raw); u.hash=""; host = u.hostname; 
    if (u.protocol !== "http:" && u.protocol !== "https:") ok = false;
    if (/^(localhost|127\.|10\.|192\.168\.|169\.254\.|0\.)/.test(host) || host.endsWith(".internal")) ok = false;
    const c = (domainCount[host]||0)+1; domainCount[host]=c; if (c > 5) ok = false;
    raw = u.toString();
  } catch(e){ ok = false; }
  out.push({ json: { url: raw, host: host, allowed: ok, etag: i.json.etag || "", last_modified: i.json.last_modified || "" } });
});
return out;

const src = $("Normalize & SSRF Guard").item.json;
const body = String($json.data || $json.body || "");
let disallow = [];
let active = false;
body.split(/\r?\n/).forEach(function(line){
  const l = line.trim(); if (!l || l[0]==="#") return;
  const m = l.match(/^([a-zA-Z-]+):\s*(.*)$/); if (!m) return;
  const key = m[1].toLowerCase(); const val = m[2].trim();
  if (key === "user-agent") active = (val === "*" || /nexus/i.test(val));
  else if (key === "disallow" && active && val) disallow.push(val);
});
let path = "/"; try { path = new URL(src.url).pathname; } catch(e){}
const blocked = disallow.some(function(d){ return path.indexOf(d) === 0; });
const allowed = src.allowed && !blocked;
return [{ json: Object.assign({}, src, { allowed: allowed }) }];

const src = $("Parse robots.txt").item.json;
const pageUrl = src.url;
let base; try { base = new URL(pageUrl); } catch(e){ base = null; }
const links = ($json.links || []).filter(Boolean);
const edges = [];
links.forEach(function(href){
  try {
    const u = new URL(href, base ? base.href : undefined); u.hash="";
    if (u.protocol!=="http:" && u.protocol!=="https:") return;
    const internal = base && u.hostname === base.hostname;
    edges.push({ from: pageUrl, to: u.toString(), host: u.hostname, internal: internal });
  } catch(e){}
});
const doc = { url: pageUrl, title: $json.title || "", text: String($json.text||""), outgoing: edges.length, edges: edges };
return [{ json: doc }];

const items = $input.all();
const pages = items.length;
const links = items.reduce(function(a,i){ return a + Number(i.json.outgoing||0); }, 0);
return [{ json: { crawledPages: pages, discoveredLinks: links, at: new Date().toISOString() } }];

const rows = $input.all().map(function(i){ return i.json; });
const outLinks = {}; const inDeg = {}; const nodes = new Set();
rows.forEach(function(r){ if(!r.from_url||!r.to_url) return; nodes.add(r.from_url); nodes.add(r.to_url); (outLinks[r.from_url]=outLinks[r.from_url]||[]).push(r.to_url); inDeg[r.to_url]=(inDeg[r.to_url]||0)+1; });
const N = nodes.size || 1; const d = 0.85; const list = Array.from(nodes);
let pr = {}; list.forEach(function(n){ pr[n] = 1/N; });
for (let iter=0; iter<20; iter++){
  const next = {}; let dangling = 0;
  list.forEach(function(n){ if(!(outLinks[n]&&outLinks[n].length)) dangling += pr[n]; });
  list.forEach(function(n){ next[n] = (1-d)/N + d*dangling/N; });
  list.forEach(function(n){ const outs = outLinks[n]||[]; const share = outs.length ? pr[n]/outs.length : 0; outs.forEach(function(t){ next[t] = (next[t]||(1-d)/N) + d*share; }); });
  pr = next;
}
// dead-link & orphan detection + domain authority
const domScore = {};
const out = list.map(function(n){
  let host=""; try { host = new URL(n).hostname; } catch(e){}
  const orphan = !(inDeg[n]>0);
  const dead = !(outLinks[n] && outLinks[n].length);
  const spam = (outLinks[n]||[]).length > 200 ? 1 : 0;
  domScore[host] = (domScore[host]||0) + pr[n];
  return { url: n, host: host, pagerank: pr[n], inLinks: inDeg[n]||0, orphan: orphan, deadEnd: dead, spam: spam };
});
out.forEach(function(o){ o.domainAuthority = Number((domScore[o.host]||0).toFixed(6)); });
out.sort(function(a,b){ return b.pagerank - a.pagerank; });
return out.slice(0, 5000).map(function(o){ return { json: o }; });

const m = $("Collect Metrics").first().json || {};
const redis = $json || {};
const documents = Number(m.documents||0);
const pages = Number(m.pages||0);
const pending = Number(m.pending_urls||0);
const errors = Number(m.recent_errors||0);
const redisUp = !!(redis.redis_version || redis.uptime_in_seconds || Object.keys(redis).length);
// prometheus-style exposition (structured logging)
const prometheus = [
  "nexus_documents_total " + documents,
  "nexus_pages_total " + pages,
  "nexus_frontier_pending " + pending,
  "nexus_errors_15m " + errors,
  "nexus_redis_up " + (redisUp?1:0)
].join("\n");
const unhealthy = errors > 20 || !redisUp;
return [{ json: { documents: documents, pages: pages, pending: pending, errors: errors, redisUp: redisUp, unhealthy: unhealthy, prometheus: prometheus, at: new Date().toISOString() } }];

